SELECT time_bucket, COUNT(play_session.id) AS value
FROM video_play_session play_session
    JOIN video_play_session filter ON play_session.id = filter.id AND filter.master_id = #{masterId}

            AND filter.video_id IN

                #{videoId}


RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket
    ON play_session.create_time >= time_bucket AND play_session.create_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket
ORDER BY time_bucket;

SELECT video.id AS videoId, COUNT(play_session.id) AS value
FROM gc_video video
    LEFT JOIN video_play_session play_session ON play_session.video_id = video.id
        AND play_session.create_time >= #{filter.start}
        AND play_session.create_time < #{filter.end}
        AND play_session.master_id = #{masterId}

    WHERE video.id IN

        #{videoId}


GROUP BY video.id;

SELECT time_bucket, COUNT(DISTINCT play_session.user_id) AS value
FROM video_play_session play_session
    JOIN video_play_session filter ON play_session.id = filter.id AND filter.master_id = #{masterId}

            AND filter.video_id IN

                #{videoId}


    RIGHT JOIN generate_series(#{filter.start}, #{filter.end}, concat(#{filter.step}, ' second')::interval) AS time_bucket
        ON play_session.create_time >= time_bucket AND play_session.create_time < time_bucket + concat(#{filter.step}, ' second')::interval
GROUP BY time_bucket
ORDER BY time_bucket;

SELECT video.id AS videoId, COUNT(DISTINCT play_session.user_id) AS value
FROM gc_video video
    LEFT JOIN video_play_session play_session ON play_session.video_id = video.id
        AND play_session.create_time >= #{filter.start}
        AND play_session.create_time < #{filter.end}
        AND play_session.master_id = #{masterId}

    WHERE video.id IN

        #{videoId}


GROUP BY video.id;
